package com.simon.mytasks;
import org.json.*;import java.util.*;
public class EmailReplyRaceTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static JSONObject d(int rev,String body)throws Exception{return new JSONObject().put("id","d").put("revision",rev).put("status","draft").put("body",body).put("can_send",true);}
 static class Host implements EmailReplyController.Host{ArrayDeque<Runnable> work=new ArrayDeque<>(),ui=new ArrayDeque<>();JSONObject data=new JSONObject();boolean valid=true;public boolean valid(){return valid;}public JSONObject read(){return data;}public boolean save(JSONObject d){data=d;return true;}public void work(Runnable r){work.add(r);}public void ui(Runnable r){ui.add(r);}void drain(){while(!work.isEmpty()||!ui.isEmpty()){while(!work.isEmpty())work.remove().run();while(!ui.isEmpty())ui.remove().run();}}}
 static final class Conflict extends Exception{final int code=409;}
 public static void main(String[] args)throws Exception{
  Host h=new Host();int[] n={0};EmailReplyController c=new EmailReplyController(new EmailReplyClient((m,p,b)->{n[0]++;if(p.endsWith("/send"))throw new java.io.IOException("lost");return d(2,b==null?"remote":b.optString("body"));}),h);c.state.accept(d(1,"initial"));c.edit("first");c.flush();c.edit("second");h.drain();check(c.state.body().equals("second"),"late save preserves new typing");c.flush();h.drain();
  EmailReplyState.put(c.state.data,"preview",new JSONObject().put("draft_revision",2).put("confirmation_id","confirm"));c.send();c.send();h.drain();check(c.state.data.optBoolean("send_pending"),"ambiguous delivery must block duplicate submission");c.reload();h.drain();check(c.state.data.optBoolean("send_pending"),"GET draft cannot resolve ambiguous outcome; require reconciliation");
  Host h2=new Host();EmailReplyController ai=new EmailReplyController(new EmailReplyClient((m,p,b)->p.contains("/assist/")?new JSONObject().put("id","job").put("status","succeeded"):d(2,"manual").put("ai_messages",new JSONArray().put(new JSONObject().put("content","Saved discussion")))),h2);ai.state.accept(d(2,"manual"));EmailReplyState.put(ai.state.data,"job_request","job");ai.poll();h2.drain();check(ai.state.draft().optJSONArray("ai_messages")!=null,"terminal AI job must refresh persistent discussion");
  Host h3=new Host();int[] reads={0};EmailReplyController retryAI=new EmailReplyController(new EmailReplyClient((m,p,b)->{if(p.endsWith("/assist"))throw new java.io.IOException("lost admission response");if(p.contains("/assist/")){reads[0]++;return new JSONObject().put("status","running");}return d(2,"manual");}),h3);retryAI.state.accept(d(2,"manual"));EmailReplyState.put(retryAI.state.data,"job",new JSONObject().put("id","old").put("status","succeeded"));retryAI.assist("discuss");h3.drain();retryAI.poll();h3.drain();check(reads[0]==1,"new ambiguous AI identity must be checked even after old terminal job");
  Host h4=new Host();EmailReplyController staleReview=new EmailReplyController(new EmailReplyClient((m,p,b)->{if(p.endsWith("/send"))throw new Conflict();return d(1,"reviewed");}),h4);staleReview.state.accept(d(1,"reviewed"));EmailReplyState.put(staleReview.state.data,"preview",new JSONObject().put("draft_revision",1).put("confirmation_id","old-context"));staleReview.send();h4.drain();check(!staleReview.state.data.optBoolean("send_pending")&&staleReview.state.editable(),"definitive stale review rejection must allow new review, not trap unknown outcome");
  Host h5=new Host();java.util.List<String> createIds=new java.util.ArrayList<>();EmailReplyController chooser=new EmailReplyController(new EmailReplyClient((m,p,b)->{createIds.add(b.getString("request_id"));throw new java.io.IOException("lost create response");}),h5);EmailReplyState.put(chooser.state.data,"task","task-a");EmailReplyState.put(chooser.state.data,"token","token-a");chooser.choose("source-a");h5.drain();chooser.choose("source-a");h5.drain();chooser.choose("source-b");h5.drain();check(createIds.get(0).equals(createIds.get(1)),"ambiguous create exact replay must retain request identity");check(!createIds.get(1).equals(createIds.get(2)),"different source cannot reuse another create payload identity");
  System.out.println("EmailReplyRaceTest passed");
 }
}
